#include <iostream>
#include <queue>
#include <vector>
#include <cstring>
#include <algorithm>
using namespace std;

char gridA[20][20], gridB[20][20];
queue<pair<int, int>> bfsQueue;
int distFromZ[20][20], distABCD[11][11][11][11];

const int dx[4] = {-1, 1, 0, 0};
const int dy[4] = {0, 0, -1, 1};

struct Edge {
    int from, to, flow, cap, next;
} edges[200005];

int edgeCount = 0;
int head[505], parent[505], visited[505];
int source = 501, sink = 502, totalFlow = 0;
int n, t, depth[505];

void addEdge(int u, int v, int capacity) {
    edges[++edgeCount] = {u, v, 0, capacity, head[u]};
    head[u] = edgeCount;
    edges[++edgeCount] = {v, u, 0, 0, head[v]};
    head[v] = edgeCount;
}

bool bfs() {
    queue<int> q;
    memset(visited, 0, sizeof(visited));
    memset(depth, 0, sizeof(depth));
    q.push(source);
    visited[source] = true;
    depth[source] = 1;

    while (!q.empty()) {
        int u = q.front(); q.pop();
        for (int i = head[u]; i; i = edges[i].next) {
            int v = edges[i].to;
            if (!visited[v] && edges[i].flow < edges[i].cap) {
                parent[v] = i;
                q.push(v);
                visited[v] = true;
                depth[v] = depth[u] + 1;
                if (v == sink) return true;
            }
        }
    }
    return false;
}

int dfs(int u, int flowLimit) {
    if (u == sink || !flowLimit) return flowLimit;
    int pushed = flowLimit;

    for (int i = head[u]; i; i = edges[i].next) {
        int v = edges[i].to;
        if (edges[i].cap > edges[i].flow && depth[v] == depth[u] + 1) {
            int delta = dfs(v, min(pushed, edges[i].cap - edges[i].flow));
            if (!delta) depth[v] = 0;
            edges[i].flow += delta;
            edges[((i - 1) ^ 1) + 1].flow -= delta;
            pushed -= delta;
            if (!pushed) break;
        }
    }
    return flowLimit - pushed;
}

void dinic() {
    while (bfs()) {
        totalFlow += dfs(source, 1000000007);
    }
}

int main() {
    cin >> n >> t;

    // Initialize distances
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            distFromZ[i][j] = 10000;
            cin >> gridA[i][j];
            if (gridA[i][j] == 'Z') {
                bfsQueue.push({i, j});
                distFromZ[i][j] = 0;
            }
            if (isdigit(gridA[i][j])) {
                addEdge(source, (i - 1) * n + j, gridA[i][j] - '0');
            }
        }
    }

    // Multi-source BFS from Z cells
    while (!bfsQueue.empty()) {
        auto [x, y] = bfsQueue.front(); bfsQueue.pop();
        for (int d = 0; d < 4; d++) {
            int nx = x + dx[d], ny = y + dy[d];
            if (nx > 0 && ny > 0 && nx <= n && ny <= n && isdigit(gridA[nx][ny]) && distFromZ[nx][ny] > distFromZ[x][y] + 1) {
                distFromZ[nx][ny] = distFromZ[x][y] + 1;
                bfsQueue.push({nx, ny});
            }
        }
    }

    // Compute pairwise distances between digit cells
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (!isdigit(gridA[i][j])) continue;

            // Reset distance array for this source
            for (int a = 1; a <= n; a++) {
                for (int b = 1; b <= n; b++) {
                    distABCD[i][j][a][b] = 10000;
                }
            }

            bfsQueue.push({i, j});
            distABCD[i][j][i][j] = 0;

            while (!bfsQueue.empty()) {
                auto [x, y] = bfsQueue.front(); bfsQueue.pop();
                for (int d = 0; d < 4; d++) {
                    int nx = x + dx[d], ny = y + dy[d];
                    if (nx > 0 && ny > 0 && nx <= n && ny <= n && isdigit(gridA[nx][ny]) && 
                        distABCD[i][j][nx][ny] > distABCD[i][j][x][y] + 1 && 
                        distABCD[i][j][x][y] < distFromZ[x][y]) {
                        distABCD[i][j][nx][ny] = distABCD[i][j][x][y] + 1;
                        bfsQueue.push({nx, ny});
                    }
                }
            }

            // Add edges based on distance constraints
            for (int k = 1; k <= n; k++) {
                for (int l = 1; l <= n; l++) {
                    if (distABCD[i][j][k][l] <= min(distFromZ[k][l], t)) {
                        addEdge((i - 1) * n + j, (k - 1) * n + l + 100, 10000);
                    }
                }
            }
        }
    }

    // Read gridB and connect to sink
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            cin >> gridB[i][j];
            if (isdigit(gridB[i][j])) {
                addEdge((i - 1) * n + j + 100, sink, gridB[i][j] - '0');
            }
        }
    }

    dinic();
    cout << totalFlow;

    return 0;
}
